query:
SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES 
WHERE TABLE_SCHEMA = DATABASE() 
AND (TABLE_NAME LIKE '%material%' OR TABLE_NAME LIKE '%essential%' OR TABLE_NAME LIKE '%oil%' OR TABLE_NAME LIKE '%product%' OR TABLE_NAME LIKE '%extract%' OR TABLE_NAME LIKE '%absolue%');

